import{_ as e,o as r,c as o,ah as d}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Accounts and roles","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/roles.md","filePath":"src/en/guide/roles.md"}'),n={name:"en/guide/roles.md"};function a(i,t,s,c,l,u){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="accounts-and-roles" tabindex="-1">Accounts and roles <a class="header-anchor" href="#accounts-and-roles" aria-label="Permalink to &quot;Accounts and roles&quot;">​</a></h1><p>Kura knows only <strong>one account per person</strong>, identified by email. An account accumulates roles over time; accounts are never recreated, even after a conversion to an organisation.</p><h2 id="the-nextboxx-account" tabindex="-1">The NextBoxx account <a class="header-anchor" href="#the-nextboxx-account" aria-label="Permalink to &quot;The NextBoxx account&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Attribute</th><th>Values</th></tr></thead><tbody><tr><td>Type</td><td><code>individual</code> or <code>organisation</code></td></tr><tr><td>Global status</td><td><code>active</code>, <code>suspended</code> (unpaid), <code>canope</code> (certified)</td></tr><tr><td>Identifier</td><td>email, case-insensitive</td></tr><tr><td>Deactivation</td><td>automatic one year after the last sign-in, data retained</td></tr></tbody></table><p>An <strong>organisation</strong> account only ever comes from converting an individual account, approved by the Administrator. The individual history (training, Canopé status) remains readable; the company name becomes the account name and the previous name stays in the request and the audit log.</p><p>The <code>suspended</code> status blocks any paid action, whatever the module. The <code>canope</code> status is granted when the certificate is delivered.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Granted by</th><th>Scope</th></tr></thead><tbody><tr><td><strong>Candidate</strong></td><td>Automatically on submission</td><td>Take the test, follow their file</td></tr><tr><td><strong>Participant</strong></td><td>Automatically on event registration</td><td>Register for events, no training access</td></tr><tr><td><strong>Learner</strong></td><td>Automatically on admission</td><td>Sign, pay, access their documents, follow training on Sève, become visible to companies once certified</td></tr><tr><td><strong>Lead Trainer</strong></td><td>Pedagogical Coordinator</td><td>Their cohorts, their remuneration, in-person attendance, retakes; no access to the QCM bank</td></tr><tr><td><strong>Coach-Tutor</strong></td><td>Pedagogical Coordinator</td><td>Their followed learners, their remuneration, their Sève space</td></tr><tr><td><strong>Pedagogical Coordinator</strong></td><td>Administrator</td><td>Catalogue, QCM, cohorts, enrolments, billing, certification, payouts, announcements, GDPR</td></tr><tr><td><strong>Admissions Advisor</strong></td><td>Administrator</td><td>Candidature handling: interview, test reminder, reasoned decision</td></tr><tr><td><strong>Business Referrer</strong></td><td>Partnerships Officer</td><td>Referred enrolments and commissions</td></tr><tr><td><strong>Marketing Partner</strong></td><td>Partnerships Officer</td><td>Invoice submission and payment tracking</td></tr><tr><td><strong>Funder</strong></td><td>Partnerships Officer</td><td>Funder area: funded learners, simplified progress, invoices for their share</td></tr><tr><td><strong>Event Funder</strong></td><td>Events Officer</td><td>Contribution declarations and funding area</td></tr><tr><td><strong>Project Holder</strong></td><td>Incubation Officer, on retention</td><td>Follow their L&#39;Éclosion project and their participation</td></tr><tr><td><strong>Events Officer</strong></td><td>Administrator</td><td>Events module and approval of related roles</td></tr><tr><td><strong>Partnerships Officer</strong></td><td>Administrator</td><td>Matching, recruitment, marketing and technology partnerships</td></tr><tr><td><strong>Incubation Officer</strong></td><td>Administrator</td><td>L&#39;Éclosion module and approval of project holders</td></tr><tr><td><strong>Direction</strong></td><td>Administrator</td><td>Consolidated read-only dashboard, investment committee</td></tr><tr><td><strong>Administrator</strong></td><td>Administrator</td><td>Account conversion, privileged roles, logs, Sève token regeneration</td></tr></tbody></table><p>Three roles are granted by the system on a business event: Candidate, Participant and Learner. All the others go through a request approved by the designated actor — never automatically.</p><h2 id="requestable-roles" tabindex="-1">Requestable roles <a class="header-anchor" href="#requestable-roles" aria-label="Permalink to &quot;Requestable roles&quot;">​</a></h2><p>From their settings, an account can request:</p><ul><li>Lead Trainer</li><li>Coach-Tutor</li><li>Business Referrer</li><li>Marketing Partner</li><li>Funder (organisation account required)</li><li>Event Funder</li></ul><p>Staff roles (Coordinator, Advisors, Officers, Direction, Administrator) are granted directly by the Administrator.</p><h2 id="approval-rules" tabindex="-1">Approval rules <a class="header-anchor" href="#approval-rules" aria-label="Permalink to &quot;Approval rules&quot;">​</a></h2><ul><li>The Administrator can approve <strong>all</strong> roles, in addition to the designated actor, so that no request is stuck behind a vacant position.</li><li>Nobody decides their own request and nobody removes their own role.</li><li>A refused role is never activated; existing roles remain untouched.</li><li>The Funder role requires an organisation account; Event Funder remains open to individual accounts.</li><li>Actions by privileged accounts (Pedagogical Coordinator, Direction, Administrator) on accounts and roles are logged with the actor and timestamp.</li></ul><h2 id="technical-permissions" tabindex="-1">Technical permissions <a class="header-anchor" href="#technical-permissions" aria-label="Permalink to &quot;Technical permissions&quot;">​</a></h2><p>Gates are defined in <code>AppServiceProvider</code> and consumed by routes (<code>can:*</code>), controllers (<code>Gate::authorize</code>) and the frontend (<code>useAccess</code>).</p><table tabindex="0"><thead><tr><th>Gate</th><th>Purpose</th></tr></thead><tbody><tr><td><code>approve-roles</code></td><td>Handling role requests</td></tr><tr><td><code>view-candidatures</code></td><td>Candidature queue and files</td></tr><tr><td><code>manage-catalogue</code></td><td>Programmes, price grid, QCM bank</td></tr><tr><td><code>view-cohorts</code>, <code>manage-cohorts</code></td><td>Viewing and running cohorts</td></tr><tr><td><code>manage-enrolments</code></td><td>Enrolments, placements, consents</td></tr><tr><td><code>manage-billing</code></td><td>Invoices, payments, credit notes, reminders</td></tr><tr><td><code>view-funded-learners</code></td><td>Funder area</td></tr><tr><td><code>view-own-commissions</code>, <code>view-own-remuneration</code></td><td>Personal referrer and trainer areas</td></tr><tr><td><code>submit-marketing-invoices</code></td><td>Marketing invoice submission</td></tr><tr><td><code>view-direction-dashboard</code></td><td>Direction dashboard</td></tr><tr><td><code>view-reporting</code></td><td>Reporting and exports</td></tr><tr><td><code>manage-communication</code></td><td>Announcements and delivery log</td></tr><tr><td><code>manage-events</code>, <code>manage-company-requests</code></td><td>Events and company request modules</td></tr><tr><td><code>manage-incubation</code>, <code>sit-investment-committee</code></td><td>L&#39;Éclosion and investment committee</td></tr><tr><td><code>manage-tech-partnerships</code></td><td>Technology partnerships</td></tr></tbody></table><h2 id="role-request-flow" tabindex="-1">Role request flow <a class="header-anchor" href="#role-request-flow" aria-label="Permalink to &quot;Role request flow&quot;">​</a></h2><ol><li>The account holder submits a request from their settings (or the Administrator creates the account).</li><li>The designated actor — or the Administrator — reviews the request.</li><li>They approve or refuse with a reason.</li><li>The holder is notified; an approved role accumulates with existing roles.</li></ol><p>See also <a href="/kura-guide/en/guide/learner-journey.html">Learner journey</a> and <a href="/kura-guide/en/guide/core-modules.html">Core modules</a>.</p>',21)])])}const g=e(n,[["render",a]]);export{m as __pageData,g as default};
